  function cleanPhone(value) {
    // убираем всё кроме цифр и +
    value = value.replace(/[^\\d+]/g, \'\');

    // оставляем + только если он первый
    if (value.indexOf(\'+\') > 0) {
      value = value.replace(/\\+/g, \'\');
    }

    // максимум 1 плюс
    if ((value.match(/\\+/g) || []).length > 1) {
      value = \'+\' + value.replace(/\\+/g, \'\');
    }

    // ограничение длины (E.164: 15 цифр + плюс)
    const digits = value.replace(/\\D/g, \'\');
    if (digits.length > 15) {
      value = (value.startsWith(\'+\') ? \'+\' : \'\') + digits.slice(0, 15);
    }

    return value;
  }

  // чтобы не ломать курсор — используем "blur-friendly" подход
  phoneInput.addEventListener(\'input\', function () {
    const start = this.selectionStart;
    const end = this.selectionEnd;

    const cleaned = cleanPhone(this.value);

    if (cleaned !== this.value) {
      this.value = cleaned;

      // стараемся восстановить курсор
      try {
        this.setSelectionRange(start, end);
      } catch (e) {}
    }
  });

  // paste
  phoneInput.addEventListener(\'paste\', function (e) {
    e.preventDefault();
    const text = (e.clipboardData || window.clipboardData).getData(\'text\');
    this.value = cleanPhone(text);
  });

  // submit safety
  const form = phoneInput.closest(\'form\');
  if (form) {
    form.addEventListener(\'submit\', function () {
      phoneInput.value = cleanPhone(phoneInput.value);
    });
  }
});
</script>
