          'cache_type' => 0,
          'snippet' => '<form action="[[~[[*id]]]]#lead-form" method="POST" class="adult-lead-form" id="adultCoursesLeadForm" autocomplete="off">
  <input type="hidden" name="csrf_token" value="[[!csrfhelper_custom@cstm_csrf? &key=`csrf_adult_courses`]]">
  [[!+fi.error.csrf_token:notempty=`<div class="adult-lead-form__error-main">[[!+fi.error.csrf_token]]</div>`]]

  <div class="adult-lead-form__grid">
    <div class="adult-lead-form__field">
      <label for="adult-courses-name">Ваше имя</label>
      <input
        type="text"
        id="adult-courses-name"
        name="name"
        value="[[+fi.name]]"
        placeholder="Как вас зовут?"
        minlength="3"
        autocomplete="name"
        required
      >
      <span class="adult-lead-form__error" data-error="name">[[+fi.error.name]]</span>
    </div>

    <div class="adult-lead-form__field">
      <label for="adult-courses-phone">Телефон</label>
      <input
        type="tel"
        id="adult-courses-phone"
        name="phone"
        value="[[+fi.phone]]"
        placeholder="+7 (000) 000-00-00"
        inputmode="tel"
        autocomplete="tel"
        maxlength="18"
        required
      >
      <span class="adult-lead-form__error" data-error="phone">[[+fi.error.phone]]</span>
    </div>
  </div>

  <div class="adult-lead-form__captcha">
    [[!recaptchav2_render]]
    [[!+fi.error.recaptchav2_error]]
    [[-!rcv3_html? &action=`[[-+rcv3Action:default=``]]` &error=`[[-+fi.error.g-recaptcha-response]]`]]
  </div>

  <label class="adult-lead-form__agree">
    <input type="checkbox" name="agreement" value="1" required>
    <span>
      Я принимаю
      <a href="/assets/files/soglasie-pd-ooo-proginskij-2026.pdf" target="_blank" rel="noopener noreferrer">пользовательское соглашение</a>
      и
      <a href="/assets/files/privacy-policy.pdf" target="_blank" rel="noopener noreferrer">политику обработки персональных данных</a>
    </span>
  </label>

  <input type="hidden" name="page" value="/[[*alias]]:adult-courses">

  <input type="hidden" name="utm_source" value="[[+utm_source]]">
  <input type="hidden" name="utm_medium" value="[[+utm_medium]]">
  <input type="hidden" name="utm_campaign" value="[[+utm_campaign]]">
  <input type="hidden" name="utm_term" value="[[+utm_term]]">
  <input type="hidden" name="utm_content" value="[[+utm_content]]">

  <button type="submit" class="adult-lead-form__submit">
    Отправить заявку
  </button>

  <input type="text" name="website" value="" tabindex="-1" autocomplete="off" style="position:absolute;left:-9999px;top:-9999px;opacity:0;pointer-events:none;height:0;width:0;">
  <input type="text" name="form_load_time" value="" tabindex="-1" autocomplete="off" style="position:absolute;left:-9999px;top:-9999px;opacity:0;pointer-events:none;height:0;width:0;">
  <input type="text" name="mouse_clicks" value="" tabindex="-1" autocomplete="off" style="position:absolute;left:-9999px;top:-9999px;opacity:0;pointer-events:none;height:0;width:0;">
</form>

<script>
document.addEventListener(\'DOMContentLoaded\', function () {
  const phoneInput = document.querySelector(\'#adult-courses-phone\');
  if (!phoneInput) return;

  function cleanPhone(value) {
    // убираем всё кроме цифр и +
    value = value.replace(/[^\\d+]/g, \'\');

    // оставляем + только если он первый
    if (value.indexOf(\'+\') > 0) {
      value = value.replace(/\\+/g, \'\');
    }

    // максимум 1 плюс
    if ((value.match(/\\+/g) || []).length > 1) {
      value = \'+\' + value.replace(/\\+/g, \'\');
    }

    // ограничение длины (E.164: 15 цифр + плюс)
    const digits = value.replace(/\\D/g, \'\');
    if (digits.length > 15) {
      value = (value.startsWith(\'+\') ? \'+\' : \'\') + digits.slice(0, 15);
    }

    return value;
  }

  // чтобы не ломать курсор — используем "blur-friendly" подход
  phoneInput.addEventListener(\'input\', function () {
    const start = this.selectionStart;
    const end = this.selectionEnd;

    const cleaned = cleanPhone(this.value);

    if (cleaned !== this.value) {
      this.value = cleaned;

      // стараемся восстановить курсор
      try {
        this.setSelectionRange(start, end);
      } catch (e) {}
    }
  });

  // paste
  phoneInput.addEventListener(\'paste\', function (e) {
    e.preventDefault();
    const text = (e.clipboardData || window.clipboardData).getData(\'text\');
    this.value = cleanPhone(text);
  });

  // submit safety
  const form = phoneInput.closest(\'form\');
  if (form) {
    form.addEventListener(\'submit\', function () {
      phoneInput.value = cleanPhone(phoneInput.value);
    });
  }
});
</script>',
